// Configuration
var token = input.get("accessToken");
var maxPages = parseInt(input.get("maxPages")) || 100;
var pageSize = parseInt(input.get("pageSize")) || 100;

// Validate token
if (!token) {
    log.error("Access token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access token is required");
    tags.trigger("error");
} else {
    // Initialize
    var allCustomers = [];
    var pagesProcessed = 0;
    var hasErrors = false;
    var errorMessage = "";

    // Build initial URL
    var baseUrl = "https://api.partnercenter.microsoft.com/v1/customers";
    var nextUrl = baseUrl + "?size=" + pageSize;
    var continuationToken = null;

    log.info("Starting Partner Center customer fetch, max pages: " + maxPages);

    // Pagination loop
    while (nextUrl && pagesProcessed < maxPages) {
        pagesProcessed++;
        log.debug("Fetching page " + pagesProcessed + ": " + nextUrl);

        // Build headers for this request
        var headers = {
            "Authorization": "Bearer " + token,
            "Accept": "application/json",
            "MS-RequestId": nodeId,
            "MS-CorrelationId": nodeId
        };

        // Add continuation token as header if we have one
        if (continuationToken) {
            headers["MS-ContinuationToken"] = continuationToken;
        }

        try {
            var response = http.get(nextUrl, headers);

            if (!response.isSuccess) {
                hasErrors = true;
                errorMessage = "API error on page " + pagesProcessed + ": HTTP " + response.statusCode;
                log.error(errorMessage);
                break;
            }

            var data = json.parse(response.body);

            // Extract customers from response
            if (data && data.items && Array.isArray(data.items)) {
                for (var i = 0; i < data.items.length; i++) {
                    allCustomers.push(data.items[i]);
                }
                log.info("Page " + pagesProcessed + ": Retrieved " + data.items.length + " customers");
            } else if (data && data.customers && Array.isArray(data.customers)) {
                for (var j = 0; j < data.customers.length; j++) {
                    allCustomers.push(data.customers[j]);
                }
                log.info("Page " + pagesProcessed + ": Retrieved " + data.customers.length + " customers");
            }

            // Check for next page - extract continuation token from headers
            nextUrl = null;
            continuationToken = null;

            if (data && data.links && data.links.next) {
                var nextLink = data.links.next;

                // Extract continuation token from headers array
                if (nextLink.headers && Array.isArray(nextLink.headers)) {
                    for (var h = 0; h < nextLink.headers.length; h++) {
                        if (nextLink.headers[h].key === "MS-ContinuationToken") {
                            continuationToken = nextLink.headers[h].value;
                            break;
                        }
                    }
                }

                // Build next URL if we have a continuation token
                if (continuationToken && nextLink.uri) {
                    nextUrl = nextLink.uri;
                    if (nextUrl.startsWith("/")) {
                        nextUrl = "https://api.partnercenter.microsoft.com" + nextUrl;
                    }
                    log.debug("Found continuation token, next URL: " + nextUrl);
                }
            }

        } catch (ex) {
            hasErrors = true;
            errorMessage = "Exception on page " + pagesProcessed + ": " + ex.message;
            log.error(errorMessage);
            break;
        }
    }

    // Set outputs
    output.set("Customers", allCustomers);
    output.setJson("CustomersJson", allCustomers);
    output.set("TotalCount", allCustomers.length);
    output.set("PagesProcessed", pagesProcessed);
    output.set("HasErrors", hasErrors);
    output.set("ErrorMessage", errorMessage);

    log.info("Completed: " + allCustomers.length + " customers in " + pagesProcessed + " pages");

    // Trigger appropriate connection tag
    if (hasErrors) {
        tags.trigger("error");
    } else if (allCustomers.length === 0) {
        tags.trigger("empty");
    } else {
        tags.trigger("success");
    }
}
